import React, { useState, useEffect } from 'react';
import axios from 'axios'; // axios import ettik
import './Product.css';
import PageTitle from '../PageTitle';

function Product() {
  const [products, setProducts] = useState([]); // state'i oluşturduk
  const [isModalOpen, setModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  // API'den ürünleri çekmek için useEffect kullanıyoruz
  useEffect(() => {
    axios.get('http://localhost:3001/products')  // Backend API endpointi
      .then((response) => {
        setProducts(response.data);  // Backend'den gelen ürünleri state'e kaydettik
      })
      .catch((error) => {
        console.error('Veri çekme hatası:', error);
      });
  }, []); // Boş array, sadece component mount olduğunda çalışacak

  // Modal'ı açma fonksiyonu
  const openModal = (product) => {
    setSelectedProduct(product);
    setModalOpen(true);
  };

  // Modal'ı kapama fonksiyonu
  const closeModal = () => {
    setModalOpen(false);
    setSelectedProduct(null);
  };

  return (
    <>
      <PageTitle title="Ürünümüz" />
      <div>
        <div className="baslik">Ürünümüz Hakkında</div>
        <div className="aboutcard">
          <div className="about-page">
            <h1 id="about-title">BeeonHive</h1>
            <p>
              BeeonHive ile birlikte kovanlarınızı web uygulamamız üzerinden kolayca takip edebilirsiniz. 2 si ana modül olmak üzere toplam
              6 modül ile birlikte kovanınızın sıcaklık ve nemini, karbondioksit ve sülfür oranını ve hatta gps modülü ile konumunu öğrenebilirsiniz.
              Müdahele edilmesi gereken durumlarda ise gerekli ilaçlamayı da yapabilirsiniz.
            </p>
          </div>
        </div>
      </div>

      <div className="product-container">
        {products.length > 0 ? (
          products.map((product) => (
            <div className="product-box" key={product._id}> {/* _id'yi kullandık */}
              <img src={product.photo} alt={product.name} className="product-image" />
              <h3>{product.name}</h3>
              <button onClick={() => openModal(product)}>Detayları Göster</button>
            </div>
          ))
        ) : (
          <p>Ürünler yükleniyor...</p> 
        )}
      </div>

      {isModalOpen && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close" onClick={closeModal}>×</button>
            <h2>{selectedProduct.name}</h2>
            <img src={selectedProduct.photo} alt={selectedProduct.name} className="product-image" />
            <p>{selectedProduct.productdetails}</p>
            <button className="close" onClick={closeModal}>Kapat</button>
            <button className="buy">Satın Al</button>
          </div>
        </div>
      )}
    </>
  );
}

export default Product;
